def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid boundary row, which determines the direction of gravity.
    boundary = next(
        (r for r in range(h)
         if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])),
        None
    )
    if boundary is None:
        boundary = next(
            (r for r in range(h)
             if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])),
            h - 1
        )

    upward = (boundary == 0)
    objects = []
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or r == boundary or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w
                            and ny != boundary
                            and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((color, cells))

    if upward:
        objects.sort(key=lambda item: min(r for r, _ in item[1]))
    else:
        objects.sort(key=lambda item: max(r for r, _ in item[1]), reverse=True)

    out = [[0] * w for _ in range(h)]
    out[boundary] = grid[boundary][:]

    for color, cells in objects:
        dr = -1 if upward else 1
        shift = 0
        while True:
            next_shift = shift + dr
            if any(
                not (0 <= r + next_shift < h)
                or out[r + next_shift][c] != 0
                for r, c in cells
            ):
                break
            shift = next_shift
        for r, c in cells:
            out[r + shift][c] = color

    return out
